<script setup>
import { ref, computed, onMounted, watch } from 'vue';
import { can, canEditContent } from '../../../lib/security/roles.js';
import { PUBLICATION_STATES, stateLabel, dateLabel, adminRequest, catalogActions, catalogRecordUrl } from '../../../lib/publicationUi.js';
import { PROGRAM_LABELS } from '../../../lib/adminUi.js';
import BarraEstados from './BarraEstados.vue';
import AccionesPublicacion from './AccionesPublicacion.vue';
const props=defineProps({module:{type:String,required:true},user:Object,documents:{type:Array,default:()=>[]},loading:Boolean,error:String});
const emit=defineEmits(['create','edit','refresh','collections']);
const selectedId=ref(''), override=ref(null), search=ref(''), status=ref(''), group=ref(''), page=ref(1), tab=ref('content');
const busy=ref(false), localError=ref(''), notice=ref(''), dialog=ref(null), pending=ref(null), note=ref(''), users=ref([]);
const books=computed(()=>props.module==='libros');
const title=computed(()=>books.value?'Libros':'Investigaciones');
const listUrl=computed(()=>books.value?'/admin/libros':'/admin/investigacion');
const doc=computed(()=>override.value||props.documents.find(d=>d._id===selectedId.value));
const groupValue=d=>books.value?d.coleccion:d.programa;
const groupLabel=d=>books.value?groupValue(d):PROGRAM_LABELS[groupValue(d)]||groupValue(d);
const authors=d=>(books.value?d.autores:d.investigadores)||[];
const cover=d=>books.value?d.portada:d.imagenURL;
const pdf=d=>books.value?d.pdf_url:d.pdfURL;
const groups=computed(()=>[...new Set(props.documents.map(groupValue).filter(Boolean))].sort());
const filtered=computed(()=>props.documents.filter(d=>(!status.value||d.editorialStatus===status.value)&&(!group.value||groupValue(d)===group.value)&&[d.titulo,groupLabel(d),...authors(d).map(a=>a.nombre)].some(t=>t?.toLocaleLowerCase('es').includes(search.value.trim().toLocaleLowerCase('es')))));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/15)));
const current=computed(()=>Math.min(page.value,pages.value));
const visible=computed(()=>filtered.value.slice((current.value-1)*15,current.value*15));
const actions=computed(()=>doc.value?catalogActions(props.user,doc.value,props.module):[]);
const canEdit=computed(()=>doc.value?.editorialStatus==='borrador'&&canEditContent(props.user,props.module,doc.value));
const history=computed(()=>[...(doc.value?.editorialHistory||[])].reverse());
const tabs=[{key:'content',label:'Contenido'},{key:'details',label:'Datos editoriales'},{key:'activity',label:'Actividad'}];
function tabKeys(event,index){let next;if(event.key==='ArrowRight')next=(index+1)%3;else if(event.key==='ArrowLeft')next=(index+2)%3;else if(event.key==='Home')next=0;else if(event.key==='End')next=2;if(next!==undefined){event.preventDefault();tab.value=tabs[next].key;document.getElementById(`catalog-tab-${tab.value}`)?.focus();}}
function open(event,item){if(!event.target.closest('a,button'))location.href=catalogRecordUrl(props.module,item._id);}
function ask(action){pending.value=action;note.value='';localError.value='';dialog.value.showModal();}
async function run(action){if(busy.value)return;busy.value=true;localError.value='';notice.value='';try{await action();}catch(e){localError.value=e.message;}finally{busy.value=false;}}
async function transition(){await run(async()=>{const data=await adminRequest('/api/editorial/transicion',{method:'POST',body:JSON.stringify({module:props.module,id:doc.value._id,rev:doc.value._rev,target:pending.value.target,note:note.value})});override.value=data.publication;dialog.value.close();notice.value='Estado actualizado.';emit('refresh');});}
async function assign(id){await run(async()=>{await adminRequest('/api/editorial/asignar',{method:'PATCH',body:JSON.stringify({module:props.module,id:doc.value._id,rev:doc.value._rev,assignedTo:id?[id]:[]})});const data=await adminRequest(books.value?'/api/libros/obtener-filtrados?admin=1':'/api/investigaciones/investigaciones?admin=1');override.value=(books.value?data:data.data.rows.map(r=>r.doc)).find(d=>d._id===selectedId.value);notice.value='Responsable actualizado.';emit('refresh');});}
watch(()=>props.documents,()=>{override.value=null;});
onMounted(async()=>{selectedId.value=new URL(location.href).searchParams.get('registro')||'';if(selectedId.value&&can(props.user,`${props.module}.assign`)){try{users.value=(await adminRequest(`/api/editorial/responsables?module=${props.module}`)).users;}catch(e){localError.value=e.message;}}});
watch(()=>props.user,async user=>{if(selectedId.value&&can(user,`${props.module}.assign`)&&!users.value.length){try{users.value=(await adminRequest(`/api/editorial/responsables?module=${props.module}`)).users;}catch(e){localError.value=e.message;}}});
</script>
<template><section class="editorial-workspace">
<template v-if="!selectedId"><div class="workspace-heading"><div><p class="eyebrow">CATÁLOGO EDITORIAL</p><h1>{{title}}</h1><p class="subtle">{{books?'Organiza tus libros y acompaña su proceso editorial.':'Del trabajo académico a la publicación: gestiona cada investigación.'}}</p></div><div class="record-actions"><button v-if="books&&can(user,'libros.manage')" class="ui-button" @click="$emit('collections')">Colecciones</button><button v-if="can(user,`${module}.create`)" class="ui-button primary" :disabled="loading" @click="$emit('create')">＋ {{books?'Nuevo libro':'Nueva investigación'}}</button></div></div>
<div class="metric-grid" aria-label="Resumen de publicaciones"><div><span>Total de registros</span><strong>{{loading?'—':documents.length}}</strong></div><div><span><i class="metric-dot amber"></i> En preparación</span><strong>{{loading?'—':documents.filter(d=>['borrador','en_revision','aprobado'].includes(d.editorialStatus)).length}}</strong></div><div><span><i class="metric-dot green"></i> Publicados</span><strong>{{loading?'—':documents.filter(d=>d.editorialStatus==='publicado').length}}</strong></div><div><span><i class="metric-dot gray"></i> Archivados</span><strong>{{loading?'—':documents.filter(d=>d.editorialStatus==='archivado').length}}</strong></div></div>
<p v-if="error" class="ui-alert error" role="alert">{{error}}</p><div class="workspace-sheet"><div class="list-toolbar"><label class="search-field"><span aria-hidden="true">⌕</span><input v-model="search" type="search" aria-label="Buscar registros" placeholder="Buscar por título, autor o categoría…" @input="page=1" /></label><div class="list-filters"><label><span class="sr-only">{{books?'Colección':'Programa'}}</span><select v-model="group" class="ui-control" @change="page=1"><option value="">{{books?'Todas las colecciones':'Todos los programas'}}</option><option v-for="g in groups" :key="g" :value="g">{{books?g:PROGRAM_LABELS[g]||g}}</option></select></label><label><span class="sr-only">Estado</span><select v-model="status" class="ui-control" @change="page=1"><option value="">Todos los estados</option><option v-for="s in PUBLICATION_STATES" :value="s.value" :key="s.value">{{s.label}}</option><option value="archivado">Archivados</option></select></label><button class="ui-button quiet" aria-label="Actualizar registros" :disabled="loading" @click="$emit('refresh')">↻ <span>Actualizar</span></button></div></div>
<div class="table-scroll" :aria-busy="loading"><table class="record-table"><thead><tr><th>Publicación</th><th>{{books?'Colección':'Programa'}}</th><th>{{books?'Autores':'Investigadores'}}</th><th>Estado</th><th>Actualización</th><th><span class="sr-only">Abrir registro</span></th></tr></thead><tbody v-if="loading"><tr v-for="n in 4" :key="n"><td colspan="6"><div class="loading-line"></div></td></tr></tbody><tbody v-else><tr v-for="item in visible" :key="item._id" class="clickable-row" @click="open($event,item)"><td><div class="publication-cell"><img v-if="cover(item)" class="list-cover" :src="cover(item)" alt="" loading="lazy"/><span v-else class="list-cover placeholder" aria-hidden="true">▤</span><a class="record-title" :href="catalogRecordUrl(module,item._id)">{{item.titulo}}</a></div></td><td>{{groupLabel(item)||'Sin clasificar'}}</td><td>{{authors(item).map(a=>a.nombre).join(', ')||'Sin autores'}}</td><td><span class="state-badge" :data-state="item.editorialStatus">{{stateLabel(item.editorialStatus)}}</span></td><td class="nowrap">{{dateLabel(item.updatedAt||item.fecha_publicacion)}}</td><td class="row-arrow" aria-hidden="true">→</td></tr></tbody></table></div>
<div v-if="!loading&&!filtered.length" class="empty-state"><h2>{{documents.length?'No encontramos coincidencias':'Tu catálogo comienza aquí'}}</h2><p>{{documents.length?'Cambia la búsqueda o los filtros.':'Los registros que puedes consultar aparecerán en esta lista.'}}</p><button v-if="documents.length" class="ui-button" @click="search='';status='';group=''">Limpiar filtros</button></div><footer class="table-footer"><span>{{filtered.length?(current-1)*15+1:0}}–{{Math.min(current*15,filtered.length)}} de {{filtered.length}} registros</span><div class="pagination"><button class="ui-button quiet" aria-label="Página anterior" :disabled="current<=1||loading" @click="page=current-1">←</button><span>{{current}} / {{pages}}</span><button class="ui-button quiet" aria-label="Página siguiente" :disabled="current>=pages||loading" @click="page=current+1">→</button></div></footer></div><p class="workspace-footnote">Abre un registro para consultar su contenido, editarlo y gestionar su estado.</p></template>
<template v-else><nav class="record-breadcrumb" aria-label="Ruta de navegación"><a :href="listUrl">← {{title}}</a><span aria-hidden="true">/</span><span>Ficha editorial</span></nav><p v-if="loading&&!doc" class="ui-alert" role="status">Cargando registro…</p><p v-if="error" class="ui-alert error" role="alert">{{error}}</p><div v-if="!loading&&!error&&!doc" class="empty-state workspace-sheet"><h1>Registro no disponible</h1><p>El registro no existe o tu cuenta no tiene acceso.</p><a :href="listUrl" class="ui-button">Volver al listado</a></div>
<template v-if="doc"><div class="record-toolbar"><div class="record-actions"><button v-if="canEdit" class="ui-button primary" :disabled="busy||loading" @click="$emit('edit',doc)">Editar {{books?'libro':'investigación'}}</button><span v-else class="subtle">{{doc.editorialStatus==='borrador'?'Consulta editorial':'Para editar el contenido, devuélvelo a borrador.'}}</span></div><a v-if="pdf(doc)" :href="pdf(doc)" class="ui-button" target="_blank" rel="noopener">Abrir PDF ↗</a></div>
<AccionesPublicacion :user="user" :doc="doc" :module="module" :busy="busy||loading" @select="ask"/><div class="record-state-row"><span class="eyebrow">PROCESO EDITORIAL</span><BarraEstados :state="doc.editorialStatus" :actions="actions" :busy="busy||loading" @select="ask"/></div><p v-if="localError&&!dialog?.open" role="alert" class="ui-alert error">{{localError}}</p><p v-if="notice" class="ui-alert" role="status">{{notice}}</p>
<div class="record-layout"><article class="workspace-sheet record-main"><header class="record-heading"><div class="record-kickers"><span class="section-label">{{books?'Libro':'Investigación'}}</span><span class="visibility-note" :class="{live:doc.editorialStatus==='publicado'}"><i></i>{{doc.editorialStatus==='publicado'?'Visible en el sitio':'Contenido interno'}}</span></div><h1>{{doc.titulo}}</h1><p class="subtle">{{authors(doc).map(a=>a.nombre).join(', ')}} · Actualizada {{dateLabel(doc.updatedAt||doc.fecha_publicacion)}}</p></header><div class="record-tabs" role="tablist" aria-label="Información de la publicación"><button v-for="(item,index) in tabs" :key="item.key" :id="`catalog-tab-${item.key}`" type="button" role="tab" :aria-selected="tab===item.key" :aria-controls="`catalog-panel-${item.key}`" :tabindex="tab===item.key?0:-1" @click="tab=item.key" @keydown="tabKeys($event,index)">{{item.label}}</button></div>
<div v-show="tab==='content'" id="catalog-panel-content" role="tabpanel" aria-labelledby="catalog-tab-content" class="record-content"><img v-if="cover(doc)" :src="cover(doc)" class="record-cover catalog-cover" alt="Portada de la publicación"/><h2 class="small-heading">Resumen</h2><p class="editorial-prose">{{doc.resumen||'Este registro aún no tiene un resumen.'}}</p><template v-if="doc.descripcion"><h2 class="small-heading">Descripción</h2><p class="editorial-prose">{{doc.descripcion}}</p></template><div v-if="doc.palabras_clave?.length" class="tag-list"><span v-for="word in doc.palabras_clave" :key="word">#{{word}}</span></div><a v-if="pdf(doc)" :href="pdf(doc)" class="document-download" target="_blank" rel="noopener"><span aria-hidden="true">▤</span><span><strong>Documento completo</strong><small>Consultar archivo PDF</small></span><span aria-hidden="true">↗</span></a></div>
<div v-show="tab==='details'" id="catalog-panel-details" role="tabpanel" aria-labelledby="catalog-tab-details" class="record-content"><h2 class="small-heading">Datos editoriales</h2><dl class="detail-grid"><div><dt>{{books?'Colección':'Programa'}}</dt><dd>{{groupLabel(doc)||'—'}}</dd></div><div><dt>Fecha de publicación</dt><dd>{{dateLabel(doc.fecha_publicacion)}}</dd></div><div v-if="books"><dt>Editorial</dt><dd>{{doc.editorial||'—'}}</dd></div><div v-if="books"><dt>ISBN</dt><dd>{{doc.isbn||'—'}}</dd></div><div v-if="books"><dt>Páginas</dt><dd>{{doc.paginas||'—'}}</dd></div><div><dt>Creado</dt><dd>{{dateLabel(doc.createdAt,true)}}</dd></div><div><dt>Actualizado</dt><dd>{{dateLabel(doc.updatedAt,true)}}</dd></div><div><dt>Estado</dt><dd>{{stateLabel(doc.editorialStatus)}}</dd></div></dl></div>
<div v-show="tab==='activity'" id="catalog-panel-activity" role="tabpanel" aria-labelledby="catalog-tab-activity" class="record-content"><h2 class="small-heading">Historial editorial</h2><ol v-if="history.length" class="activity-timeline"><li v-for="(event,index) in history" :key="index"><span class="timeline-dot"></span><div><strong>{{stateLabel(event.to)}}</strong><p class="subtle">{{dateLabel(event.at,true)}} · {{event.actorId===user?.id?user.name:'Equipo editorial'}}</p><p class="subtle">{{stateLabel(event.from)}} → {{stateLabel(event.to)}}</p><p v-if="event.note" class="activity-note">{{event.note}}</p></div></li></ol><p v-else class="subtle">Todavía no hay cambios de estado registrados.</p></div></article>
<aside class="record-sidebar"><div class="workspace-sheet side-card"><h2>Resumen</h2><dl><div><dt>Estado</dt><dd><span class="state-badge" :data-state="doc.editorialStatus">{{stateLabel(doc.editorialStatus)}}</span></dd></div><div><dt>{{books?'Colección':'Programa'}}</dt><dd>{{groupLabel(doc)||'—'}}</dd></div><div><dt>{{books?'Autores':'Investigadores'}}</dt><dd>{{authors(doc).map(a=>a.nombre).join(', ')}}</dd></div></dl></div><div class="workspace-sheet side-card"><h2>Responsable de edición</h2><label v-if="can(user,`${module}.assign`)" class="field-label"><span class="sr-only">Asignar responsable</span><select class="ui-control" :value="doc.assignedTo?.[0]||''" :disabled="busy||loading" @change="assign($event.target.value)"><option value="">Sin asignar</option><option v-for="person in users" :key="person.id" :value="person.id">{{person.name}}</option></select></label><p v-else class="subtle">{{doc.assignedTo?.includes(user?.id)?user.name:doc.assignedTo?.length?'Responsable asignado':'Sin asignar'}}</p><p class="field-help">La persona asignada edita dentro de sus permisos.</p></div><p class="record-help">Archivar conserva el registro y lo retira del sitio público.</p></aside></div></template></template>
<dialog ref="dialog" class="modal editorial-modal" aria-labelledby="catalog-action-title" @cancel="busy&&$event.preventDefault()"><form class="modal-box ui-dialog" @submit.prevent="transition"><p class="eyebrow">PROCESO EDITORIAL</p><h2 id="catalog-action-title">{{pending?.label}}</h2><p class="subtle">{{pending?.target==='publicado'?'El contenido y sus archivos quedarán disponibles en el sitio.':doc?.editorialStatus==='publicado'?'El registro dejará de estar visible en el sitio.':'El registro cambiará de estado y la acción quedará en su historial.'}}</p><p class="dialog-record-title">{{doc?.titulo}}</p><label class="field-label">Observaciones (opcional)<textarea v-model="note" class="ui-control" rows="3" maxlength="2000" placeholder="Añade contexto para el equipo…"></textarea></label><p v-if="localError" class="ui-alert error" role="alert">{{localError}}</p><div class="dialog-actions"><button type="button" class="ui-button" :disabled="busy" @click="dialog.close()">Cancelar</button><button class="ui-button primary" :disabled="busy">{{busy?'Procesando…':'Confirmar cambio'}}</button></div></form></dialog>
</section></template>
